package tools

import (
	"context"
	_ "embed"
	"encoding/json"
	"fmt"

	"github.com/google/jsonschema-go/jsonschema"
	"github.com/hangtiancheng/yukino-code/apps/dejavu/internal/tools/operations"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// Generated by apps/mcp/scripts/export-go-contract.ts. These are the public
// TypeScript schemas, including enums, bounds, required fields and defaults.
//
//go:embed contracts.json
var contractJSON []byte

type contract struct {
	InputSchema json.RawMessage      `json:"inputSchema"`
	Annotations *mcp.ToolAnnotations `json:"annotations"`
	Meta        mcp.Meta             `json:"_meta"`
}

var contracts = func() map[string]contract {
	var result map[string]contract
	if err := json.Unmarshal(contractJSON, &result); err != nil {
		panic(err)
	}
	return result
}()

// AddTool uses the TS contract and Zod's object/default/trim semantics before
// decoding the Go arguments. The original request is preserved: MongoDB relies
// on the command's original key order, which a map round trip would erase.
func AddTool[In any](server *mcp.Server, tool *mcp.Tool, handler mcp.ToolHandlerFor[In, any]) {
	c, ok := contracts[tool.Name]
	if !ok {
		panic(fmt.Sprintf("missing TypeScript contract for %s", tool.Name))
	}
	tool.InputSchema = c.InputSchema
	tool.Annotations = c.Annotations
	tool.Meta = c.Meta
	var schema jsonschema.Schema
	if err := json.Unmarshal(c.InputSchema, &schema); err != nil {
		panic(err)
	}
	resolved, err := schema.Resolve(nil)
	if err != nil {
		panic(err)
	}
	var rawSchema map[string]any
	if err := json.Unmarshal(c.InputSchema, &rawSchema); err != nil {
		panic(err)
	}
	server.AddTool(tool, func(ctx context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		args := map[string]any{}
		if len(req.Params.Arguments) > 0 {
			if err := json.Unmarshal(req.Params.Arguments, &args); err != nil {
				return inputError(err), nil
			}
		}
		if args == nil {
			return inputError(fmt.Errorf("arguments must be an object")), nil
		}
		if tool.Name == MySQLTool {
			for _, key := range []string{"connection_url", "dsn"} {
				if _, exists := args[key]; exists {
					return inputError(fmt.Errorf("mysql_tool does not accept %s; configure mysql.username, mysql.password and connection fields in JSON", key)), nil
				}
			}
		}
		stripUnknown(args, rawSchema)
		trimArguments(tool.Name, args)
		if err := resolved.ApplyDefaults(&args); err != nil {
			return inputError(err), nil
		}
		if err := resolved.Validate(args); err != nil {
			return inputError(err), nil
		}
		raw, err := json.Marshal(args)
		if err != nil {
			return inputError(err), nil
		}
		var in In
		if err := json.Unmarshal(raw, &in); err != nil {
			return inputError(err), nil
		}
		result, _, err := handler(ctx, req, in)
		if err != nil {
			return inputError(err), nil
		}
		return result, nil
	})
}

func inputError(err error) *mcp.CallToolResult {
	return &mcp.CallToolResult{
		Content: []mcp.Content{&mcp.TextContent{Text: err.Error()}},
		IsError: true,
	}
}

func stripUnknown(value any, schema map[string]any) {
	switch object := value.(type) {
	case map[string]any:
		properties, ok := schema["properties"].(map[string]any)
		if !ok {
			return // z.record and arbitrary JSON retain their keys.
		}
		for key, entry := range object {
			property, exists := properties[key]
			if !exists {
				if schema["additionalProperties"] == nil || schema["additionalProperties"] == false {
					delete(object, key)
				}
				continue
			}
			if nested, ok := property.(map[string]any); ok {
				stripUnknown(entry, nested)
			}
		}
	case []any:
		if items, ok := schema["items"].(map[string]any); ok {
			for _, item := range object {
				stripUnknown(item, items)
			}
		}
	}
}

func trimArguments(name string, args map[string]any) {
	keys := []string{"connection_url", "base_url"}
	switch name {
	case MongoDBTool, MilvusTool:
		keys = append(keys, "database")
	case Clickhouse:
		keys = append(keys, "database", "format", "user")
	case MinioTool:
		keys = append(keys, "endpoint", "region", "bucket")
	case KafkaTool:
		keys = append(keys, "brokers", "client_id", "topic", "group_id")
		if topics, ok := args["topics"].([]any); ok {
			for i, topic := range topics {
				if text, ok := topic.(string); ok {
					topics[i] = operations.TrimJS(text)
				}
			}
		}
		for _, key := range []string{"assignments", "partitions"} {
			if entries, ok := args[key].([]any); ok {
				for _, entry := range entries {
					if object, ok := entry.(map[string]any); ok {
						trimKeys(object, []string{"topic"})
					}
				}
			}
		}
	}
	trimKeys(args, keys)
}

func trimKeys(args map[string]any, keys []string) {
	for _, key := range keys {
		if text, ok := args[key].(string); ok {
			args[key] = operations.TrimJS(text)
		}
	}
}
